cd /dayjs && cat > test/zz_dbg.test.js <<'EOF'
import dayjs from '../src'
import utc from '../src/plugin/utc'
import timezone from '../src/plugin/timezone'
dayjs.extend(utc)
dayjs.extend(timezone)
const NY = 'America/New_York'
const typeToPos = { year:0, month:1, day:2, hour:3, minute:4, second:5 }
it('dbg', () => {
  const d = dayjs
  const tzOffset = (timestamp, timezone) => {
    const date = new Date(timestamp)
    const dtf = new Intl.DateTimeFormat('en-US', { hour12:false, timeZone: timezone, year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', second:'2-digit' })
    const fr = dtf.formatToParts(date)
    const filled = []
    for (let i=0;i<fr.length;i+=1){ const {type,value}=fr[i]; const pos=typeToPos[type]; if(pos>=0) filled[pos]=parseInt(value,10) }
    const utcString = `${filled[0]}-${filled[1]}-${filled[2]} ${filled[3]}:${filled[4]}:${filled[5]}:000`
    const utcTs = d.utc(utcString).valueOf()
    let asTS = +date
    const over = asTS % 1000
    asTS -= over
    console.log('  tzOffset', timestamp, new Date(timestamp).toISOString(), '->', utcString, (utcTs-asTS)/60000)
    return (utcTs - asTS) / (60*1000)
  }
  const localTs = d.utc('2012-03-11 01:59:59').valueOf()
  const o0 = tzOffset(+d(), NY)
  console.log('localTs', localTs, new Date(localTs).toISOString(), 'o0', o0)
  let utcGuess = localTs - (o0*60*1000)
  const o2 = tzOffset(utcGuess, NY)
  console.log('utcGuess', utcGuess, new Date(utcGuess).toISOString(), 'o2', o2)
  utcGuess -= (o2-o0)*60*1000
  const o3 = tzOffset(utcGuess, NY)
  console.log('utcGuess2', utcGuess, new Date(utcGuess).toISOString(), 'o3', o3)
  const r = dayjs.tz('2012-03-11 01:59:59', NY)
  console.log('result', r.format(), r.$d.toISOString(), r.$offset, r.valueOf())
})
EOF
TZ=UTC npx jest test/zz_dbg --coverage=false 2>&1 | head -40

